        "required": ["status", "class"],
        "properties": {
          "status": { "enum": ["stated", "default"] },
          "class": { "enum": ["document_rule", "house_default"] }
        }
      },
      "then": {
        "required": ["citations"],
        "properties": { "citations": { "minItems": 1 } }
      }
    }
  ],
  "$defs": {
    "citation": {
      "type": "object",
      "required": ["doc", "anchor", "quote"],
      "additionalProperties": false,
      "properties": {
        "doc": { "type": "string", "pattern": "^[a-z][a-z0-9_-]*$" },
        "anchor": { "type": "string", "minLength": 1 },
        "quote": { "type": "string", "minLength": 1 }
